package com.bank.consistency;

import java.math.BigDecimal;
import java.util.logging.*;

public class ConsistencyDemo {
    private static final Logger log = Logger.getLogger("Consistency");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // STRONG: money — read always reflects the latest committed write
        StrongStore money = new StrongStore();
        money.write("balance:SAV2001", "1000000");
        money.write("balance:SAV2001", "950000");  // after a transfer
        log.info(() -> "STRONG balance (always latest) = " + money.read("balance:SAV2001"));

        // EVENTUAL: like count — replicas lag then converge
        EventualStore feed = new EventualStore(2);  // 2 replicas
        feed.write("likes:post-1", "100");          // written to leader only (async)
        log.info(() -> "EVENTUAL read before sync (stale) = " + feed.readReplica("likes:post-1"));
        feed.propagate();                            // async replication catches up
        log.info(() -> "EVENTUAL read after sync (converged) = " + feed.readReplica("likes:post-1"));

        // READ-YOUR-WRITES: user sees their own write immediately
        ReadYourWrites ryw = new ReadYourWrites(feed);
        ryw.write("SAV2001", "post:Rajesh's first post");
        log.info(() -> "own read (immediate) = " + ryw.readOwn("SAV2001", "post:Rajesh's first post"));
        log.info(() -> "friend read (may lag) = " + feed.readReplica("post:Rajesh's first post"));
    }
}

